use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let num = input.as_u64().unwrap();
    if num == 0 {
        Value::from(-1)
    } else {
        let mut num = num;
        let mut pos = 0;
        while num > 0 {
            num >>= 1;
            pos += 1;
        }
        Value::from(pos)
    }
}
